#!/bin/sh
# Fetch the images of docker-compose.yaml by digest into images/ (generated by hydo compose; hydo-build
# never pulls). Needs hydo-fetch-image (it comes with hydo) and network access, once.
# It fetches the images this machine builds: x86_64 on Linux, arm64 on a Mac. Name
# x86_64, arm64 or all as the argument to choose (sh fetch-images.sh all).
set -eu
cd "$(dirname "$0")"
A=${1:-}
[ -n "$A" ] || case "$(uname -s)" in Darwin) A=arm64;; *) A=x86_64;; esac
case "$A" in x86_64|arm64|all) ;; *) echo "fetch-images.sh: x86_64, arm64 or all (got $A)" >&2; exit 2;; esac
F=${HYDO_FETCH_IMAGE:-$(command -v hydo-fetch-image || true)}
[ -n "$F" ] || { echo "fetch-images.sh: hydo-fetch-image not found (put hydo's bin directory on PATH, or set HYDO_FETCH_IMAGE)" >&2; exit 1; }
mkdir -p images
[ "$A" = x86_64 ] || [ -e images/getmeili-meilisearch-v1.57.0-arm64-oci ] || "$F" docker.io/getmeili/meilisearch sha256:ed87e30e7638d091520d0ecd0cca70e4ca62c770534a744dfb7bc6e5666b1ce1 getmeili/meilisearch:v1.57.0 images/getmeili-meilisearch-v1.57.0-arm64-oci
[ "$A" = arm64 ] || [ -f images/getmeili-meilisearch-v1.57.0-amd64.docker.tar ] || "$F" docker.io/getmeili/meilisearch sha256:540676d5fdde739d8a3f276e700d8844893ddab292f694165de884f2091f4cc6 getmeili/meilisearch:v1.57.0 images/getmeili-meilisearch-v1.57.0-amd64.docker.tar
[ "$A" = arm64 ] || ls -ld images/getmeili-meilisearch-v1.57.0-amd64.docker.tar
[ "$A" = x86_64 ] || ls -ld images/getmeili-meilisearch-v1.57.0-arm64-oci
